+      --text: #eef2ff;
+      --cyan: #70e5ff;
+      --violet: #a98bff;
+      --pink: #ff7dbe;
+      --green: #61e5b1;
+      --amber: #ffc875;
+      --shadow: 0 24px 80px rgba(0, 0, 0, .35);
+      --radius: 24px;
+      --max: 1240px;
+    }
+    * { box-sizing: border-box; }
+    html { scroll-behavior: smooth; }
+    body {
+      margin: 0;
+      color: var(--text);
+      background:
+        radial-gradient(circle at 12% 8%, rgba(112, 229, 255, .12), transparent 25rem),
+        radial-gradient(circle at 90% 18%, rgba(169, 139, 255, .12), transparent 28rem),
+        linear-gradient(180deg, #080b16 0%, #0b1020 46%, #080b16 100%);
+      font-family: "Segoe UI", Tahoma, Arial, sans-serif;
+      line-height: 1.8;
+      overflow-x: hidden;
+    }
+    body::before {
+      content: "";
+      position: fixed;
+      inset: 0;
+      pointer-events: none;
+      opacity: .22;
+      background-image: linear-gradient(rgba(255,255,255,.035) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.035) 1px, transparent 1px);
+      background-size: 56px 56px;
+      mask-image: linear-gradient(to bottom, black, transparent 85%);
+      z-index: -1;
+    }
+    #space { position: fixed; inset: 0; width: 100%; height: 100%; pointer-events: none; opacity: .72; z-index: -2; }
+    a { color: inherit; text-decoration: none; }
+    button { font: inherit; }
+    .progress { position: fixed; top: 0; right: 0; height: 3px; width: 0; background: linear-gradient(90deg, var(--cyan), var(--violet), var(--pink)); z-index: 20; box-shadow: 0 0 18px var(--cyan); }
+    .nav { position: fixed; top: 18px; left: 50%; transform: translateX(-50%); width: min(calc(100% - 32px), var(--max)); display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 10px 14px 10px 18px; border: 1px solid var(--line); border-radius: 999px; background: rgba(8, 11, 22, .62); backdrop-filter: blur(18px); z-index: 10; box-shadow: var(--shadow); }
+    .brand { display: flex; align-items: center; gap: 10px; font-weight: 800; letter-spacing: -.02em; white-space: nowrap; }
+    .brand-mark { width: 34px; height: 34px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fff, var(--cyan) 18%, var(--violet) 56%, #291c70 100%); box-shadow: 0 0 22px rgba(112,229,255,.58); position: relative; }
+    .brand-mark::after { content: ""; position: absolute; inset: 7px; border: 1px solid rgba(255,255,255,.75); border-radius: 50%; transform: rotateX(65deg); }
+    .nav-links { display: flex; gap: 4px; overflow: auto; scrollbar-width: none; }
+    .nav-links::-webkit-scrollbar { display: none; }
+    .nav-links a { color: var(--muted); font-size: 13px; padding: 7px 11px; border-radius: 999px; transition: .25s ease; white-space: nowrap; }
+    .nav-links a:hover, .nav-links a:focus-visible { color: var(--text); background: rgba(112,229,255,.1); outline: none; }
+    .wrap { width: min(calc(100% - 36px), var(--max)); margin: auto; }
+    .hero { min-height: 860px; display: grid; align-items: center; position: relative; padding: 150px 0 80px; perspective: 1200px; }
+    .hero-grid { display: grid; grid-template-columns: 1.03fr .97fr; align-items: center; gap: 62px; }
+    .eyebrow { color: var(--cyan); text-transform: uppercase; letter-spacing: .16em; font-size: 12px; font-weight: 800; margin-bottom: 18px; }
+    h1, h2, h3, p { margin-top: 0; }
+    h1 { font-size: clamp(3rem, 7vw, 6.7rem); line-height: .98; letter-spacing: -.075em; margin-bottom: 24px; max-width: 720px; }
+    h1 span { display: block; background: linear-gradient(105deg, #fff 8%, var(--cyan) 44%, var(--violet) 82%); -webkit-background-clip: text; background-clip: text; color: transparent; }
+    .hero-copy { color: #c4cee7; font-size: clamp(1.04rem, 1.8vw, 1.35rem); max-width: 610px; }
+    .hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin: 30px 0 28px; }
+    .btn { display: inline-flex; align-items: center; justify-content: center; min-height: 46px; padding: 0 19px; border-radius: 999px; border: 1px solid var(--line); color: var(--text); background: rgba(255,255,255,.055); cursor: pointer; transition: transform .25s ease, background .25s ease, border-color .25s ease; }
+    .btn:hover, .btn:focus-visible { transform: translateY(-3px); background: rgba(112,229,255,.12); border-color: rgba(112,229,255,.55); outline: none; }
+    .btn-primary { color: #07121d; border-color: transparent; background: linear-gradient(110deg, var(--cyan), #a9f4ff); font-weight: 800; box-shadow: 0 10px 30px rgba(112,229,255,.2); }
