from pathlib import Path
from hashlib import sha256

def digest(p):
    h=sha256()
    with p.open('rb') as f:
        for c in iter(lambda:f.read(1024*1024),b''): h.update(c)
    return h.hexdigest()
for src,dst in [('/sdcard/Nexus_Brain/Nexus_Brain/brain','/sdcard/NEXUS_LLM_WIKI/raw/legacy/brain'),('/sdcard/Nexus_Brain/Nexus_Brain/chats','/sdcard/NEXUS_LLM_WIKI/raw/legacy/chats')]:
    s=Path(src); d=Path(dst); mismatches=[]
    for p in s.rglob('*'):
        if p.is_file():
            q=d/p.relative_to(s)
            if not q.exists() or digest(p)!=digest(q): mismatches.append(str(p))
    print(src, 'hash_mismatches=',len(mismatches))
    if mismatches: print('\n'.join(mismatches[:10]))
